type UnhashedShortNanoPackDefinition = Omit<ShortNanoPackDefinition, "heroCompositions"> & Readonly<{
  heroCompositions: readonly Omit<ShortNanoPackHeroComposition, "promptSha256">[];
}>;

function defineShortNanoPack(pack: UnhashedShortNanoPackDefinition): ShortNanoPackDefinition {
  return {
    ...pack,
    heroCompositions: pack.heroCompositions.map((hero) => ({
      ...hero,
      promptSha256: createHash("sha256").update(hero.prompt, "utf8").digest("hex"),
    })),
  };
}
