export function getShortNanoPackDefinition(styleId: string): ShortNanoPackDefinition | undefined {
  return SHORT_NANO_PACKS.find((pack) => pack.styleId === styleId || pack.packageId === styleId);
}

export function getShortNanoPackPrompts(styleId: string): string[] | undefined {
  const pack = getShortNanoPackDefinition(styleId);
  return pack ? pack.heroCompositions.map((hero) => hero.prompt) : undefined;
}

export function isShortNanoPackStyle(styleId: string): boolean {
  return Boolean(getShortNanoPackDefinition(styleId));
}

export const shortNanoPackDefinitions = SHORT_NANO_PACKS;
